INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (111, '¿CUAL ES LA MULTA POR NO PORTAR EL CINTURÓN DE SEGURIDAD?', 11, 4, 'Q 50', 'Q 400', 'Q 200', 'Q 300', 'C');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (112, '¿CUAL ES LA MULTA POR NO RESPETAR EL LIMITE DE VELOCIDAD?', 12, 4, 'Q 100', 'Q 200', 'Q 500', 'Q 300', 'D');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (113, '¿A CUANTO ASCIENDE LA MULTA POR NO PORTAR LICENCIA DE CONDUCIR?', 13, 4, '50', '100', '200', '300', 'C');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (114, '¿CUAL ES LA MULTA POR NO PORTAR EL EQUIPAMIENTO BÁSICO DE SU VEHÍCULO?', 14, 4, '100', '200', '300', '400', 'B');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (115, '¿EL ARCEN ES UNA FRANJA PARALELA A LA CALZADA Y PUEDEN USARLA? ', 15, 4, 'Para rebasar', 'Los vehículos con alguna emergencia ', 'Estacionarse', 'Todas son correctas ', 'B');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (116, '¿POR REGLA GENERAL ESTA PROHIBIDO? ', 16, 4, 'Bocinarle al automóvil de en frente para apurarlo', 'Rebasar por el carril izquierdo', 'Detenerse cuando exista la señal de alto ', 'Ninguna es correcta ', 'A');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (117, '¿UD. VA MANEJANDO Y EL COPILOTO TIRA BASURA POR LA VENTANA? ', 17, 4, 'Multan al piloto por ser el conductor ', 'Es permitido hacerlo y no multan a nadie ', 'Multan a quien tiro la basura ', 'Ninguna es correcta ', 'A');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (118, '¿CARRIL QUE SIRVE PARA REALIZAR UN DESVIO EN UNA CALZADA? ', 18, 4, 'Carril auxiliar ', 'Carril de aceleración ', 'Carril de desaceleracion ', 'Ninguna es correcta ', 'A');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (119, '¿QUE NOS INDICA EL SEMÁFORO EN ROJO? ', 19, 4, 'Continuar la marcha ', 'Aproximación a cruce ', 'Ceder el paso', 'Detenerse obligatoriamente ', 'D');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (120, '¿DE QUE COLOR ESTÁN PINTADAS LAS SEÑALES PREVENTIVAS?', 20, 4, 'Amarillo y azul ', 'Amarillo y negro ', 'Amarillo y rojo', 'Amarillo y blanco ', 'B');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (121, '¿QUE FUNCIÓN CUMPLE LA LINEA DOBLE AMARILLA PINTADA EN LA CARRETERA?', 21, 4, 'Divide carriles en un solo sentido', 'Permite rebasar o adelantar', 'Divide grupos de carriles que van en diferentes sentido de circulacion', 'Ninguna es correcta', 'C');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (122, '¿DE QUE COLORES ESTÁN PINTADAS LAS SEÑALES CIRCUNSTANCIALES (TEMPORALES)?', 22, 4, 'Azul, verde y blanco ', 'Blanco,rojo y negro ', 'Naranja ', 'Nada', 'C');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (123, '¿EN QUE CASO SE APLICAN MULTAS DE Q1,000?', 23, 4, 'Por faltarle el respeto a la autoridad ', 'Por pasar un semáforo en rojo ', 'Por atropellar un peatón ', 'Todas son correctas ', 'A');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (124, '¿QUE ES LA LICENCIA DE CONDUCIR?', 24, 4, 'Documento que identifica al conductor ', 'Documento de identifica al pasajero ', 'Documento que identifica al vehículo ', 'Ninguna es correcta', 'A');
INSERT INTO Eva_Teo (ID_Teorica, Texto_Preg, Num_Preg, Num_resp, Opcion_A, Opcion_B, Opcion_C, Opcion_D, Resp_Correcta) VALUES (125, '¿POR SU PESO COMO SE CLASIFICA UNA MOTOCICLETA?', 25, 4, 'Pesada ', 'Ligero ', 'Especial ', 'Ninguna es correcta ', 'B');
